INSERT INTO quotes (id, quote, author, used) VALUES (1, 'A house divided against itself cannot stand.', 'Abraham Lincoln', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (2, 'Important principles may, and must, be inflexible.', 'Abraham Lincoln', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (3, 'I destroy my enemies when I make them my friends.', 'Abraham Lincoln', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (4, 'You have to do your own growing no matter how tall your grandfather was.', 'Abraham Lincoln', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (5, 'Most people are about as happy as they make up their minds to be', 'Abraham Lincoln', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (6, 'Most folks are about as happy as they make up their minds to be.', 'Abraham Lincoln', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (7, 'Give me six hours to chop down a tree and I will spend the first four sharpening the axe.', 'Abraham Lincoln', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (8, 'When you have got an elephant by the hind legs and he is trying to run away, it''s best to let him run.', 'Abraham Lincoln', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (9, 'The best thing about the future is that it only comes one day at a time.', 'Abraham Lincoln', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (10, 'Character is like a tree and reputation like a shadow. The shadow is what we think of it; the tree is the real thing.', 'Abraham Lincoln', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (11, 'As our case is new, we must think and act anew.', 'Abraham Lincoln', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (12, 'Be sure you put your feet in the right place, then stand firm.', 'Abraham Lincoln', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (13, 'Always bear in mind that your own resolution to succeed is more important than any one thing.', 'Abraham Lincoln', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (14, 'I walk slowly, but I never walk backward.', 'Abraham Lincoln', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (15, 'Truth is generally the best vindication against slander.', 'Abraham Lincoln', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (16, 'Most folks are as happy as they make up their minds to be.', 'Abraham Lincoln', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (17, 'I will prepare and some day my chance will come.', 'Abraham Lincoln', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (18, 'What is necessary to change a person is to change his awareness of himself.', 'Abraham Maslow', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (19, 'No act of kindness, no matter how small, is ever wasted.', 'Aesop', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (20, 'If you let go a little, you will have a little peace. If you let go a lot, you will have a lot of peace.', 'Ajahn Chah', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (21, 'No valid plans for the future can be made by those who have no capacity for living now.', 'Alan Watts', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (22, 'Autumn is a second spring when every leaf is a flower.', 'Albert Camus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (23, 'In the depth of winter, I finally learned that there was within me an invincible summer.', 'Albert Camus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (24, 'God always takes the simplest way.', 'Albert Einstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (25, 'Learn from yesterday, live for today, hope for tomorrow.', 'Albert Einstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (26, 'The only real valuable thing is intuition.', 'Albert Einstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (27, 'Once we accept our limits, we go beyond them.', 'Albert Einstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (28, 'Life is like riding a bicycle. To keep your balance you must keep moving.', 'Albert Einstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (29, 'Feeling and longing are the motive forces behind all human endeavor and human creations.', 'Albert Einstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (30, 'I believe that a simple and unassuming manner of life is best for everyone, best both for the body and the mind.', 'Albert Einstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (31, 'Try not to become a man of success, but rather try to become a man of value.', 'Albert Einstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (32, 'When the solution is simple, God is answering.', 'Albert Einstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (33, 'A man should look for what is, and not for what he thinks should be.', 'Albert Einstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (34, 'Imagination is more important than knowledge. For while knowledge defines all we currently know and understand, imagination points to all we might yet discover and create.', 'Albert Einstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (35, 'If A is success in life, then A equals x plus y plus z. Work is x; y is play; and z is keeping your mouth shut.', 'Albert Einstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (36, 'Reality is merely an illusion, albeit a very persistent one.', 'Albert Einstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (37, 'Peace cannot be kept by force. It can only be achieved by understanding.', 'Albert Einstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (38, 'We cannot solve our problems with the same thinking we used when we created them.', 'Albert Einstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (39, 'If you can''t explain it simply, you don''t understand it well enough.', 'Albert Einstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (40, 'Imagination is everything. It is the preview of life''s coming attractions.', 'Albert Einstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (41, 'The true sign of intelligence is not knowledge but imagination.', 'Albert Einstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (42, 'In the middle of every difficulty lies opportunity.', 'Albert Einstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (43, 'Setting an example is not the main means of influencing another, it is the only means.', 'Albert Einstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (44, 'Logic will get you from A to B. Imagination will take you everywhere.', 'Albert Einstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (45, 'Great ideas often receive violent opposition from mediocre minds.', 'Albert Einstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (46, 'Anyone who doesn''t take truth seriously in small matters cannot be trusted in large ones either.', 'Albert Einstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (47, 'There are only two ways to live your life. One is as though nothing is a miracle. The other is as though everything is a miracle.', 'Albert Einstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (48, 'One may say the eternal mystery of the world is its comprehensibility.', 'Albert Einstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (49, 'A person who never made a mistake never tried anything new.', 'Albert Einstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (50, 'I have no special talent. I am only passionately curious.', 'Albert Einstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (51, 'Winners have simply formed the habit of doing things losers don''t like to do.', 'Albert Gray', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (52, 'Do something wonderful, people may imitate it.', 'Albert Schweitzer', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (53, 'We should all be thankful for those people who rekindle the inner spirit.', 'Albert Schweitzer', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (54, 'One who gains strength by overcoming obstacles possesses the only strength which can overcome adversity.', 'Albert Schweitzer', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (55, 'Wherever a man turns he can find someone who needs him.', 'Albert Schweitzer', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (56, 'Constant kindness can accomplish much. As the sun makes ice melt, kindness causes misunderstanding, mistrust, and hostility to evaporate.', 'Albert Schweitzer', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (57, 'Success is not the key to happiness. Happiness is the key to success. If you love what you are doing, you will be successful.', 'Albert Schweitzer', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (58, 'An optimist is a person who sees a green light everywhere, while the pessimist sees only the red spotlight... The truly wise person is colour-blind.', 'Albert Schweitzer', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (59, 'Never say there is nothing beautiful in the world any more. There is always something to make you wonder in the shape of a tree, the trembling of a leaf.', 'Albert Schweitzer', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (60, 'There is only one corner of the universe you can be certain of improving, and that''s your own self.', 'Aldous Huxley', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (61, 'Experience is not what happens to a man. It is what a man does with what happens to him.', 'Aldous Huxley', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (62, 'Do good by stealth, and blush to find it fame.', 'Alexander Pope', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (63, 'Blessed is the man who expects nothing, for he shall never be disappointed.', 'Alexander Pope', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (64, 'There is nothing impossible to him who will try.', 'Alexander the Great', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (65, 'All great men are gifted with intuition. They know without reasoning or analysis, what they need to know.', 'Alexis Carrel', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (66, 'Trust only movement. Life happens at the level of events, not of words. Trust movement.', 'Alfred Adler', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (67, 'There are two ways to slide easily through life: to believe everything or to doubt everything; both ways save us from thinking.', 'Alfred Korzybski', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (68, 'Saying thank you is more than good manners. It is good spirituality.', 'Alfred Painter', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (69, 'Learn all you can from the mistakes of others. You won''t have time to make them all yourself.', 'Alfred Sheinwold', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (70, 'The happiness of a man in this life does not consist in the absence but in the mastery of his passions.', 'Alfred Tennyson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (71, 'The art of progress is to preserve order amid change, and to preserve change amid order.', 'Alfred Whitehead', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (72, 'No person is your friend who demands your silence, or denies your right to grow.', 'Alice Walker', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (73, 'Some people are always grumbling because roses have thorns; I am thankful that thorns have roses.', 'Alphonse Karr', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (74, 'Speak when you are angry and you will make the best speech you will ever regret.', 'Ambrose Bierce', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (75, 'Never do things others can do and will do, if there are things others cannot do or will not do.', 'Amelia Earhart', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (76, 'From little acorns mighty oaks do grow.', 'American proverb', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (77, 'Without passion man is a mere latent force and possibility, like the flint which awaits the shock of the iron before it can give forth its spark.', 'Amiel', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (78, 'Love at first sight is easy to understand; its when two people have been looking at each other for a lifetime that it becomes a miracle.', 'Amy Bloom', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (79, 'I am like a falling star who has finally found her place next to another in a lovely constellation, where we will sparkle in the heavens forever.', 'Amy Tan', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (80, 'Life shrinks or expands in proportion to one''s courage.', 'Anaïs Nin', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (81, 'The possession of knowledge does not kill the sense of wonder and mystery. There is always more mystery.', 'Anaïs Nin', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (82, 'Dreams pass into the reality of action. From the actions stems the dream again; and this interdependence produces the highest form of living.', 'Anaïs Nin', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (83, 'The personal life deeply lived always expands into truths beyond itself.', 'Anaïs Nin', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (84, 'Age does not protect you from love. But love, to some extent, protects you from age.', 'Anaïs Nin', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (85, 'The dream was always running ahead of me. To catch up, to live for a moment in unison with it, that was the miracle.', 'Anaïs Nin', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (86, 'There is not one big cosmic meaning for all, there is only the meaning we each give to our life.', 'Anaïs Nin', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (87, 'To accomplish great things, we must dream as well as act.', 'Anatole France', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (88, 'To accomplish great things, we must not only act, but also dream; not only plan, but also believe.', 'Anatole France', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (89, 'It is better to understand a little than to misunderstand a lot.', 'Anatole France', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (90, 'You learn to speak by speaking, to study by studying, to run by running, to work by working; in just the same way, you learn to love by loving.', 'Anatole France', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (91, 'One does not discover new lands without consenting to lose sight of the shore for a very long time.', 'André Gide', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (92, 'The most decisive actions of our life... are most often unconsidered actions.', 'André Gide', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (93, 'If you smile when no one else is around, you really mean it.', 'Andy Rooney', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (94, 'They say that time changes things, but you actually have to change them yourself.', 'Andy Warhol', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (95, 'While we try to teach our children all about life, our children teach us what life is all about.', 'Angela Schwindt', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (96, 'To follow, without halt, one aim: There is the secret of success.', 'Anna Pavlova', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (97, 'If we had no winter, the spring would not be so pleasant; if we did not sometimes taste of adversity, prosperity would not be so welcome.', 'Anne Bradstreet', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (98, 'All our talents increase in the using, and the every faculty, both good and bad, strengthen by exercise.', 'Anne Bronte', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (99, 'We all live with the objective of being happy; our lives are all different and yet the same.', 'Anne Frank', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (100, 'How wonderful it is that nobody need wait a single moment before starting to improve the world.', 'Anne Frank', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (101, 'No one has ever become poor by giving.', 'Anne Frank', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (102, 'Parents can only give good advice or put them on the right paths, but the final forming of a persons character lies in their own hands.', 'Anne Frank', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (103, 'Joy is the best makeup.', 'Anne Lamott', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (104, 'If one is estranged from oneself, then one is estranged from others too. If one is out of touch with oneself, then one cannot touch others.', 'Anne Lindbergh', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (105, 'Life is a process. We are a process. The universe is a process.', 'Anne Schaef', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (106, 'Trusting our intuition often saves us from disaster.', 'Anne Wilson Schaef', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (107, 'How we spend our days is, of course, how we spend our lives.', 'Annie Dillard', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (108, 'Listen to your intuition. It will tell you everything you need to know.', 'Anthony D''Angelo', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (109, 'It is only with the heart that one can see rightly, what is essential is invisible to the eye.', 'Antoine de Saint-Exupery', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (110, 'I know but one freedom and that is the freedom of the mind.', 'Antoine de Saint-Exupery', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (111, 'Love does not consist of gazing at each other, but in looking together in the same direction.', 'Antoine de Saint-Exupery', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (112, 'Discover the great ideas that lie inside you by discovering the power of sleep.', 'Arianna Huffington', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (113, 'Your ability to learn faster than your competition is your only sustainable competitive advantage.', 'Arie de Gues', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (114, 'Well begun is half done.', 'Aristotle', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (115, 'Change in all things is sweet.', 'Aristotle', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (116, 'It is the mark of an educated mind to be able to entertain a thought without accepting it.', 'Aristotle', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (117, 'Happiness depends upon ourselves.', 'Aristotle', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (118, 'In all things of nature there is something of the marvellous.', 'Aristotle', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (119, 'Those that know, do. Those that understand, teach.', 'Aristotle', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (120, 'Criticism is something you can easily avoid by saying nothing, doing nothing, and being nothing.', 'Aristotle', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (121, 'Moral excellence comes about as a result of habit. We become just by doing just acts, temperate by doing temperate acts, brave by doing brave acts.', 'Aristotle', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (122, 'The energy of the mind is the essence of life.', 'Aristotle', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (123, 'If one way be better than another, that you may be sure is natures way.', 'Aristotle', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (124, 'Whenever you have eliminated the impossible, whatever remains, however improbable, must be the truth.', 'Arthur Conan Doyle', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (125, 'Mediocrity knows nothing higher than itself, but talent instantly recognizes genius.', 'Arthur Conan Doyle', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (126, 'Of course there is no formula for success except perhaps an unconditional acceptance of life and what it brings.', 'Arthur Rubinstein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (127, 'Every man takes the limits of his own field of vision for the limits of the world.', 'Arthur Schopenhauer', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (128, 'When I dare to be powerful, to use my strength in the service of my vision, then it becomes less and less important whether I am afraid.', 'Audre Lorde', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (129, 'The world is a book, and those who do not travel read only a page.', 'Augustinus Sanctus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (130, 'Yesterday is history. Tomorrow is a mystery. And today? Today is a gift. That is why we call it the present.', 'Babatunde Olatunji', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (131, 'Yesterdays home runs don''t win today''s games.', 'Babe Ruth', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (132, 'Without courage, wisdom bears no fruit.', 'Baltasar Gracian', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (133, 'If you''re walking down the right path and you''re willing to keep walking, eventually you''ll make progress.', 'Barack Obama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (134, 'Focusing your life solely on making a buck shows a poverty of ambition. It asks too little of yourself. And it will leave you unfulfilled.', 'Barack Obama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (135, 'Change will not come if we wait for some other person or some other time. We are the ones we''ve been waiting for. We are the change that we seek.', 'Barack Obama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (136, 'Don''t wait for your feelings to change to take the action. Take the action and your feelings will change.', 'Barbara Baron', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (137, 'We need to find the courage to say NO to the things and people that are not serving us if we want to rediscover ourselves and live our lives with authenticity.', 'Barbara De Angelis', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (138, 'The first step to getting the things you want out of life is this: decide what you want.', 'Ben Stein', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (139, 'We cannot hold a torch to light another''s path without brightening our own.', 'Ben Sweetland', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (140, 'The secret of success is constancy to purpose.', 'Benjamin Disraeli', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (141, 'Action may not always bring happiness; but there is no happiness without action.', 'Benjamin Disraeli', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (142, 'Through perseverance many people win success out of what seemed destined to be certain failure.', 'Benjamin Disraeli', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (143, 'Never apologize for showing feelings. When you do so, you apologize for the truth.', 'Benjamin Disraeli', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (144, 'One secret of success in life is for a man to be ready for his opportunity when it comes.', 'Benjamin Disraeli', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (145, 'The greatest good you can do for another is not just to share your riches but to reveal to him his own.', 'Benjamin Disraeli', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (146, 'The greatest good you can do for another is not just share your riches, but reveal to them their own.', 'Benjamin Disraeli', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (147, 'Ignorance never settle a question.', 'Benjamin Disraeli', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (148, 'Action may not always bring happiness, but there is no happiness without action.', 'Benjamin Disraeli', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (149, 'Never apologize for showing feeling. When you do so, you apologize for truth.', 'Benjamin Disraeli', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (150, 'We make our own fortunes and we call them fate.', 'Benjamin Disraeli', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (151, 'Well done is better than well said.', 'Benjamin Franklin', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (152, 'One today is worth two tomorrows.', 'Benjamin Franklin', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (153, 'There never was a good knife made of bad steel.', 'Benjamin Franklin', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (154, 'Watch the little things; a small leak will sink a great ship.', 'Benjamin Franklin', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (155, 'Experience keeps a dear school, but fools will learn in no other.', 'Benjamin Franklin', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (156, 'There surely is in human nature an inherent propensity to extract all the good out of all the evil.', 'Benjamin Haydon', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (157, 'Trust yourself. You know more than you think you do.', 'Benjamin Spock', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (158, 'Yesterday I dared to struggle. Today I dare to win.', 'Bernadette Devlin', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (159, 'Life''s challenges are not supposed to paralyse you, they''re supposed to help you discover who you are.', 'Bernice Johnson Reagon', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (160, 'Life''s challenges are not supposed to paralyze you, they''re supposed to help you discover who you are.', 'Bernice Johnson Reagon', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (161, 'The happiness that is genuinely satisfying is accompanied by the fullest exercise of our faculties and the fullest realization of the world in which we live.', 'Bertrand Russell', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (162, 'It is easier to live through someone else than to become complete yourself.', 'Betty Friedan', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (163, 'Success is a lousy teacher. It seduces smart people into thinking they can''t lose.', 'Bill Gates', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (164, 'Our passion is our strength.', 'Billie Armstrong', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (165, 'Trust your own instinct. Your mistakes might as well be your own, instead of someone else''s.', 'Billy Wilder', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (166, 'We must not allow ourselves to become like the system we oppose.', 'Bishop Desmond Tutu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (167, 'The heart has its reasons which reason knows not of.', 'Blaise Pascal', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (168, 'Kind words do not cost much. Yet they accomplish much.', 'Blaise Pascal', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (169, 'Man is equally incapable of seeing the nothingness from which he emerges and the infinity in which he is engulfed.', 'Blaise Pascal', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (170, 'Imagination disposes of everything; it creates beauty, justice, and happiness, which are everything in this world.', 'Blaise Pascal', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (171, 'The least movement is of importance to all nature. The entire ocean is affected by a pebble.', 'Blaise Pascal', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (172, 'We are all something, but none of us are everything.', 'Blaise Pascal', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (173, 'We know the truth, not only by the reason, but by the heart.', 'Blaise Pascal', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (174, 'We must learn our limits. We are all something, but none of us are everything.', 'Blaise Pascal', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (175, 'Set your goals high, and don''t stop till you get there.', 'Bo Jackson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (176, 'All I can say about life is, Oh God, enjoy it!', 'Bob Newhart', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (177, 'All know the way; few actually walk it.', 'Bodhidharma', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (178, 'Excellence is to do a common thing in an uncommon way.', 'Booker Washington', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (179, 'The world cares very little about what a man or woman knows; it is what a man or woman is able to do that counts.', 'Booker Washington', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (180, 'No yesterdays are ever wasted for those who give themselves to today.', 'Brendan Francis', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (181, 'Goals are the fuel in the furnace of achievement.', 'Brian Tracy', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (182, 'Whatever we expect with confidence becomes our own self-fulfilling prophecy.', 'Brian Tracy', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (183, 'You can only grow if you''re willing to feel awkward and uncomfortable when you try something new.', 'Brian Tracy', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (184, 'There is never enough time to do everything, but there is always enough time to do the most important thing.', 'Brian Tracy', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (185, 'You have within you, right now, everything you need to deal with whatever the world can throw at you.', 'Brian Tracy', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (186, 'Creativity doesn''t wait for that perfect moment. It fashions its own perfect moments out of ordinary ones.', 'Bruce Garrabrandt', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (187, 'If you spend too much time thinking about a thing, you''ll never get it done.', 'Bruce Lee', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (188, 'A wise man can learn more from a foolish question than a fool can learn from a wise answer.', 'Bruce Lee', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (189, 'Notice that the stiffest tree is most easily cracked, while the bamboo or willow survives by bending with the wind.', 'Bruce Lee', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (190, 'Always be yourself, express yourself, have faith in yourself, do not go out and look for a successful personality and duplicate it.', 'Bruce Lee', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (191, 'Take no thought of who is right or wrong or who is better than. Be not for or against.', 'Bruce Lee', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (192, 'Take things as they are. Punch when you have to punch. Kick when you have to kick.', 'Bruce Lee', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (193, 'I''m not in this world to live up to your expectations and you''re not in this world to live up to mine.', 'Bruce Lee', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (194, 'To know oneself is to study oneself in action with another person.', 'Bruce Lee', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (195, 'As you think, so shall you become.', 'Bruce Lee', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (196, 'Mistakes are always forgivable, if one has the courage to admit them.', 'Bruce Lee', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (197, 'If you love life, don''t waste time, for time is what life is made up of.', 'Bruce Lee', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (198, 'All fixed set patterns are incapable of adaptability or pliability. The truth is outside of all fixed patterns.', 'Bruce Lee', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (199, 'The less effort, the faster and more powerful you will be.', 'Bruce Lee', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (200, 'To hell with circumstances; I create opportunities.', 'Bruce Lee', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (201, 'Im not in this world to live up to your expectations and you''re not in this world to live up to mine.', 'Bruce Lee', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (202, 'Knowing is not enough, we must apply. Willing is not enough, we must do.', 'Bruce Lee', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (203, 'Do not pray for an easy life, pray for the strength to endure a difficult one', 'Bruce Lee', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (204, 'Be happy, but never satisfied.', 'Bruce Lee', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (205, 'There is nothing in a caterpillar that tells you it''s going to be a butterfly.', 'Buckminster Fuller', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (206, 'You never change things by fighting the existing reality. To change something, build a new model that makes the existing model obsolete', 'Buckminster Fuller', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (207, 'Peace comes from within. Do not seek it without.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (208, 'Work out your own salvation. Do not depend on others.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (209, 'He is able who thinks he is able.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (210, 'Those who are free of resentful thoughts surely find peace.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (211, 'What we think, we become.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (212, 'It is better to travel well than to arrive.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (213, 'The mind is everything. What you think you become.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (214, 'In separateness lies the world''s great misery, in compassion lies the world''s true strength.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (215, 'Happiness comes when your work and words are of benefit to yourself and others.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (216, 'Just as a candle cannot burn without fire, men cannot live without a spiritual life.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (217, 'If you light a lamp for somebody, it will also brighten your path.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (218, 'Your worst enemy cannot harm you as much as your own unguarded thoughts.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (219, 'The way is not in the sky. The way is in the heart.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (220, 'Three things cannot be long hidden: the sun, the moon, and the truth.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (221, 'You, yourself, as much as anybody in the entire universe, deserve your love and affection.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (222, 'You will not be punished for your anger, you will be punished by your anger.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (223, 'The thought manifests as the word. The word manifests as the deed. The deed develops into habit. And the habit hardens into character.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (224, 'In a controversy the instant we feel anger we have already ceased striving for the truth, and have begun striving for ourselves.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (225, 'Do not overrate what you have received, nor envy others. He who envies others does not obtain peace of mind.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (226, 'To keep the body in good health is a duty... otherwise we shall not be able to keep our mind strong and clear.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (227, 'There are only two mistakes one can make along the road to truth; not going all the way, and not starting.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (228, 'To live a pure unselfish life, one must count nothing as ones own in the midst of abundance.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (229, 'Do not dwell in the past, do not dream of the future, concentrate the mind on the present moment.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (230, 'We are what we think. All that we are arises with our thoughts. With our thoughts, we make the world.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (231, 'Your work is to discover your world and then with all your heart give yourself to it.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (232, 'All that we are is the result of what we have thought. The mind is everything. What we think we become.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (233, 'The foot feels the foot when it feels the ground.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (234, 'No one saves us but ourselves. No one can and no one may. We ourselves must walk the path.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (235, 'When you realize how perfect everything is you will tilt your head back and laugh at the sky.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (236, 'Thousands of candles can be lighted from a single candle, and the life of the candle will not be shortened. Happiness never decreases by being shared.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (237, 'He who experiences the unity of life sees his own Self in all beings, and all beings in his own Self, and looks on everything with an impartial eye.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (238, 'In the sky, there is no distinction of east and west; people create distinctions out of their own minds and then believe them to be true.', 'Buddha', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (239, 'Thousands of candles can be lit from a single, and the life of the candle will not be shortened. Happiness never decreases by being shared.', 'Buddha', 0);
