INSERT INTO quotes (id, quote, author, used) VALUES (414, 'The Superior Man is aware of Righteousness, the inferior man is aware of advantage.', 'Confucius', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (415, 'Fine words and an insinuating appearance are seldom associated with true virtue', 'Confucius', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (416, 'Our greatest glory is not in never falling, but in rising every time we fall.', 'Confucius', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (417, 'I hear and I forget. I see and I remember. I do and I understand.', 'Confucius', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (418, 'Ability will never catch up with the demand for it.', 'Confucius', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (419, 'The superior man acts before he speaks, and afterwards speaks according to his action.', 'Confucius', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (420, 'Learning without reflection is a waste, reflection without learning is dangerous.', 'Confucius', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (421, 'If you look into your own heart, and you find nothing wrong there, what is there to worry about? What is there to fear?', 'Confucius', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (422, 'Sincerity is the way of Heaven. The attainment of sincerity is the way of men.', 'Confucius', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (423, 'To give ones self earnestly to the duties due to men, and, while respecting spiritual beings, to keep aloof from them, may be called wisdom.', 'Confucius', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (424, 'He who wishes to secure the good of others, has already secured his own.', 'Confucius', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (425, 'Life is really simple, but we insist on making it complicated.', 'Confucius', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (426, 'Life is a succession of moments. To live each one is to succeed.', 'Corita Kent', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (427, 'When performance exceeds ambition, the overlap is called success.', 'Cullen Hightower', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (428, 'To want to be what one can be is purpose in life.', 'Cynthia Ozick', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (429, 'What matters is the value we''ve created in our lives, the people we''ve made happy and how much we''ve grown as people.', 'Daisaku Ikeda', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (430, 'The person who lives life fully, glowing with life''s energy, is the person who lives a successful life.', 'Daisaku Ikeda', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (431, 'True happiness means forging a strong spirit that is undefeated, no matter how trying our circumstances.', 'Daisaku Ikeda', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (432, 'Genuine sincerity opens people''s hearts, while manipulation causes them to close.', 'Daisaku Ikeda', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (433, 'If we look at the world with a love of life, the world will reveal its beauty to us.', 'Daisaku Ikeda', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (434, 'If you lose today, win tomorrow. In this never-ending spirit of challenge is the heart of a victor.', 'Daisaku Ikeda', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (435, 'Be kind whenever possible. It is always possible.', 'Dalai Lama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (436, 'Sleep is the best meditation.', 'Dalai Lama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (437, 'I believe that we are fundamentally the same and have the same basic potential.', 'Dalai Lama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (438, 'Love and compassion open our own inner life, reducing stress, distrust and loneliness.', 'Dalai Lama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (439, 'More often than not, anger is actually an indication of weakness rather than of strength.', 'Dalai Lama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (440, 'By going beyond your own problems and taking care of others, you gain inner strength, self-confidence, courage, and a greater sense of calm.', 'Dalai Lama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (441, 'If we have a positive mental attitude, then even when surrounded by hostility, we shall not lack inner peace.', 'Dalai Lama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (442, 'Genuine love should first be directed at oneself if we do not love ourselves, how can we love others?', 'Dalai Lama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (443, 'With the realization of ones own potential and self-confidence in ones ability, one can build a better world.', 'Dalai Lama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (444, 'The key to transforming our hearts and minds is to have an understanding of how our thoughts and emotions work.', 'Dalai Lama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (445, 'I find hope in the darkest of days, and focus in the brightest. I do not judge the universe.', 'Dalai Lama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (446, 'People take different roads seeking fulfilment and happiness. Just because they''re not on your road doesn''t mean they''ve gotten lost.', 'Dalai Lama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (447, 'With realization of ones own potential and self-confidence in ones ability, one can build a better world.', 'Dalai Lama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (448, 'Happiness is not something ready made. It comes from your own actions.', 'Dalai Lama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (449, 'Remember that sometimes not getting what you want is a wonderful stroke of luck.', 'Dalai Lama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (450, 'Consider that not only do negative thoughts and emotions destroy our experience of peace, they also undermine our health.', 'Dalai Lama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (451, 'The greatest antidote to insecurity and the sense of fear is compassion it brings one back to the basis of one''s inner strength', 'Dalai Lama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (452, 'There is no need for temples, no need for complicated philosophies. My brain and my heart are my temples; my philosophy is kindness.', 'Dalai Lama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (453, 'Happiness mainly comes from our own attitude, rather than from external factors.', 'Dalai Lama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (454, 'It is difficult to achieve a spirit of genuine cooperation as long as people remain indifferent to the feelings and happiness of others.', 'Dalai Lama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (455, 'The most important thing is transforming our minds, for a new way of thinking, a new outlook: we should strive to develop a new inner world.', 'Dalai Lama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (456, 'Compassion and happiness are not a sign of weakness but a sign of strength.', 'Dalai Lama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (457, 'See the positive side, the potential, and make an effort.', 'Dalai Lama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (458, 'Happiness does not come about only due to external circumstances; it mainly derives from inner attitudes.', 'Dalai Lama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (459, 'Genuine love should first be directed at oneself - if we do not love ourselves, how can we love others?', 'Dalai Lama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (460, 'The greatest antidote to insecurity and the sense of fear is compassion - it brings one back to the basis of one''s inner strength', 'Dalai Lama', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (461, 'Most of the important things in the world have been accomplished by people who have kept on trying when there seemed to be no hope at all.', 'Dale Carnegie', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (462, 'When fate hands us a lemon, let''s try to make lemonade.', 'Dale Carnegie', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (463, 'Success is getting what you want. Happiness is wanting what you get.', 'Dale Carnegie', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (464, 'The winner ain''t the one with the fastest car it''s the one who refuses to lose.', 'Dale Earnhardt', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (465, 'Give it all you''ve got because you never know if there''s going to be a next time.', 'Danielle Ingrum', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (466, 'It''s important to know that words don''t move mountains. Work, exacting work moves mountains.', 'Danilo Dolci', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (467, 'The secret to a rich life is to have more beginnings than endings.', 'Dave Weinbaum', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (468, 'Be here now. Be someplace else later. Is that so complicated?', 'David Bader', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (469, 'Tomorrow belongs to those who can hear it coming', 'David Bowie', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (470, 'A successful person is one who can lay a firm foundation with the bricks that others throw at him or her.', 'David Brinkley', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (471, 'No day in which you learn something is a complete loss.', 'David Eddings', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (472, 'Wisdom is knowing what to do next; Skill is knowing how ot do it, and Virtue is doing it.', 'David Jordan', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (473, 'Real success is finding your lifework in the work that you love.', 'David McCullough', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (474, 'Success in business requires training and discipline and hard work. But if you''re not frightened by these things, the opportunities are just as great today as they ever were.', 'David Rockefeller', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (475, 'We cannot change our memories, but we can change their meaning and the power they have over us.', 'David Seamans', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (476, 'When you make a choice, you change the future.', 'Deepak Chopra', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (477, 'Small opportunities are often the beginning of great enterprises.', 'Demosthenes', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (478, 'There are two primary choices in life: to accept conditions as they exist, or accept the responsibility for changing them.', 'Denis Waitley', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (479, 'There are two primary choices in life: to accept conditions as they exist, or accept responsibility for changing them.', 'Denis Waitley', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (480, 'You must welcome change as the rule but not as your ruler.', 'Denis Waitley', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (481, 'Happiness cannot be travelled to, owned, earned, worn or consumed. Happiness is the spiritual experience of living every minute with love, grace and gratitude.', 'Denis Waitley', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (482, 'A dream is your creative vision for your life in the future. You must break out of your current comfort zone and become comfortable with the unfamiliar and the unknown.', 'Denis Waitley', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (483, 'The only person who never makes mistakes is the person who never does anything.', 'Denis Waitley', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (484, 'The future cannot be predicted, but futures can be invented. It was man''s ability to invent which has made human society what it is.', 'Dennis Gabor', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (485, 'We see things not as they are, but as we are. Our perception is shaped by our previous experiences.', 'Dennis Kimbro', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (486, 'The fox has many tricks. The hedgehog has but one. But that is the best of all.', 'Desiderius Erasmus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (487, 'Just as a flower, which seems beautiful has color but no perfume, so are the fruitless words of a man who speaks them but does them not.', 'Dhammapada', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (488, 'Do not give your attention to what others do or fail to do; give it to what you do or fail to do.', 'Dhammapada', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (489, 'The desire to create is one of the deepest yearnings of the human soul.', 'Dieter F. Uchtdorf', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (490, 'When some one reminded him that the people of Sinope had sentenced him to exile, he said, And I sentenced them to stay at home.', 'Diogenes', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (491, 'The art of being a slave is to rule one''s master.', 'Diogenes', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (492, 'A philosopher named Aristippus, who had quite willingly sucked up to Dionysus and won himself a spot at his court, saw Diogenes cooking lentils for a meal. If you would only learn to compliment Dionysus, you wouldn''t have to live on lentils. Diogenes replied, But if you would only learn to live on lentils, you wouldn''t have to flatter Dionysus.', 'Diogenes', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (493, 'A man of ability and the desire to accomplish something can do anything.', 'Donald Kircher', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (494, 'Everything in life is luck.', 'Donald Trump', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (495, 'Money was never a big motivation for me, except as a way to keep score. The real excitement is playing the game.', 'Donald Trump', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (496, 'You have to think anyway, so why not think big?', 'Donald Trump', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (497, 'What separates the winners from the losers is how a person reacts to each new twist of fate.', 'Donald Trump', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (498, 'Sometimes by losing a battle you find a new way to win the war.', 'Donald Trump', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (499, 'Gratitude is riches. Complaint is poverty.', 'Doris Day', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (500, 'Until you make peace with who you are, you''ll never be content with what you have.', 'Doris Mortman', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (501, 'Fear grows in darkness; if you think there''s a bogeyman around, turn on the light.', 'Dorothy Thompson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (502, 'Only when we are no longer afraid do we begin to live.', 'Dorothy Thompson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (503, 'Be your own hero, it''s cheaper than a movie ticket.', 'Doug Horton', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (504, 'Wisdom is the reward you get for a lifetime of listening when you''d have preferred to talk.', 'Doug Larson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (505, 'Human beings, who are almost unique in having the ability to learn from the experience of others, are also remarkable for their apparent disinclination to do so.', 'Douglas Adams', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (506, 'Aim for success, not perfection. Never give up your right to be wrong, because then you will lose the ability to learn new things and move forward with your life.', 'Dr. David M. Burns', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (507, 'Don''t cry because it''s over. Smile because it happened.', 'Dr. Seuss', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (508, 'It takes courage to grow up and become who you really are.', 'E. E. Cummings', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (509, 'One must be fond of people and trust them if one is not to make a mess of life.', 'E. M. Forster', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (510, 'It is not uncommon for people to spend their whole life waiting to start living.', 'Eckhart Tolle', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (511, 'You cannot find yourself by going into the past. You can find yourself by coming into the present.', 'Eckhart Tolle', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (512, 'The past has no power to stop you from being present now. Only your grievance about the past can do that.', 'Eckhart Tolle', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (513, 'Whenever something negative happens to you, there is a deep lesson concealed within it.', 'Eckhart Tolle', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (514, 'You do not become good by trying to be good, but by finding the goodness that is already within you.', 'Eckhart Tolle', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (515, 'The greater part of human pain is unnecessary. It is self-created as long as the unobserved mind runs your life.', 'Eckhart Tolle', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (516, 'Friends are those rare people who ask how we are and then wait to hear the answer.', 'Ed Cunningham', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (517, 'Slow down and enjoy life. It''s not only the scenery you miss by going too fast - you also miss the sense of where you are going and why.', 'Eddie Cantor', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (518, 'The universe is full of magical things, patiently waiting for our wits to grow sharper.', 'Eden Phillpotts', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (519, 'Those who dream by day are cognizant of many things which escape those who dream only by night.', 'Edgar Allan Poe', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (520, 'The inner fire is the most important thing mankind possesses.', 'Edith Södergran', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (521, 'If only we''d stop trying to be happy we''d have a pretty good time.', 'Edith Wharton', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (522, 'A man is not old as long as he is seeking something.', 'Edmond Rostand', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (523, 'Nobody made a greater mistake than he who did nothing because he could do only a little.', 'Edmund Burke', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (524, 'I am glad that I paid so little attention to good advice; had I abided by it I might have been saved from some of my most valuable mistakes.', 'Edna Millay', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (525, 'The cosmos is neither moral or immoral; only people are. He who would move the world must first move himself.', 'Edward Ericson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (526, 'The winds and waves are always on the side of the ablest navigators.', 'Edward Gibbon', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (527, 'On every thorn, delightful wisdom grows, In every rill a sweet instruction flows.', 'Edward Young', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (528, 'It is better to have enough ideas for some of them to be wrong, than to be always right by having no ideas at all.', 'Edward de Bono', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (529, 'Every action of our lives touches on some chord that will vibrate in eternity.', 'Edwin Chapin', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (530, 'We have committed the Golden Rule to memory; let us now commit it to life.', 'Edwin Markham', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (531, 'Through meditation and by giving full attention to one thing at a time, we can learn to direct attention where we choose.', 'Eknath Easwaran', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (532, 'There is no failure except in no longer trying.', 'Elbert Hubbard', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (533, 'To avoid criticism, do nothing, say nothing, be nothing.', 'Elbert Hubbard', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (534, 'A little more persistence, a little more effort, and what seemed hopeless failure may turn to glorious success.', 'Elbert Hubbard', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (535, 'A failure is a man who has blundered but is not capable of cashing in on the experience.', 'Elbert Hubbard', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (536, 'The final proof of greatness lies in being able to endure criticism without resentment.', 'Elbert Hubbard', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (537, 'The greatest mistake you can make in life is to be continually fearing you will make one.', 'Elbert Hubbard', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (538, 'No one can make you feel inferior without your consent.', 'Eleanor Roosevelt', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (539, 'Do one thing every day that scares you.', 'Eleanor Roosevelt', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (540, 'The future belongs to those who believe in the beauty of their dreams.', 'Eleanor Roosevelt', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (541, 'I think somehow we learn who we really are and then live with that decision.', 'Eleanor Roosevelt', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (542, 'Friendship with oneself is all important because without it one cannot be friends with anybody else in the world.', 'Eleanor Roosevelt', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (543, 'Remember always that you not only have the right to be an individual, you have an obligation to be one.', 'Eleanor Roosevelt', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (544, 'People grow through experience if they meet life honestly and courageously. This is how character is built.', 'Eleanor Roosevelt', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (545, 'It is not fair to ask of others what you are unwilling to do yourself.', 'Eleanor Roosevelt', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (546, 'You must do the things you think you cannot do.', 'Eleanor Roosevelt', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (547, 'I believe that we are solely responsible for our choices, and we have to accept the consequences of every deed, word, and thought throughout our lifetime.', 'Elisabeth Kubler-Ross', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (548, 'I''m not interested in age. People who tell me their age are silly. You''re as old as you feel.', 'Elizabeth Arden', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (549, 'Light tomorrow with today!', 'Elizabeth Browning', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (550, 'Love doesn''t make the world go round, love is what makes the ride worthwhile.', 'Elizabeth Browning', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (551, 'Who so loves, believes the impossible.', 'Elizabeth Browning', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (552, 'He who angers you conquers you.', 'Elizabeth Kenny', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (553, 'I endeavour to be wise when I cannot be merry, easy when I cannot be glad, content with what cannot be mended and patient when there is no redress.', 'Elizabeth Montagu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (554, 'It isn''t where you come from, it''s where you''re going that counts.', 'Ella Fitzgerald', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (555, 'The truest greatness lies in being kind, the truest wisdom in a happy mind.', 'Ella Wilcox', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (556, 'Bite off more than you can chew, then chew it.', 'Ella Williams', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (557, 'Don''t ruin the present with the ruined past.', 'Ellen Gilchrist', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (558, 'The cure for boredom is curiosity. There is no cure for curiosity.', 'Ellen Parr', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (559, 'Take heed: you do not find what you do not seek.', 'English proverb', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (560, 'Freedom is the right to live as we wish.', 'Epictetus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (561, 'Difficulties are things that show a person what they are.', 'Epictetus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (562, 'If you wish to be a writer, write.', 'Epictetus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (563, 'Practice yourself, for heavens sake in little things, and then proceed to greater.', 'Epictetus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (564, 'Make the best use of what is in your power, and take the rest as it happens.', 'Epictetus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (565, 'Nature gave us one tongue and two ears so we could hear twice as much as we speak.', 'Epictetus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (566, 'He is a wise man who does not grieve for the things which he has not, but rejoices for those which he has.', 'Epictetus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (567, 'There is only one way to happiness and that is to cease worrying about things which are beyond the power of our will.', 'Epictetus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (568, 'If you seek truth you will not seek victory by dishonourable means, and if you find truth you will become invincible.', 'Epictetus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (569, 'When you are offended at any man''s fault, turn to yourself and study your own failings. Then you will forget your anger.', 'Epictetus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (570, 'Know, first, who you are, and then adorn yourself accordingly.', 'Epictetus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (571, 'Men are disturbed not by things, but by the view which they take of them.', 'Epictetus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (572, 'We have two ears and one mouth so that we can listen twice as much as we speak.', 'Epictetus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (573, 'Not every difficult and dangerous thing is suitable for training, but only that which is conducive to success in achieving the object of our effort.', 'Epictetus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (574, 'No man is free who is not master of himself.', 'Epictetus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (575, 'It''s not what happens to you, but how you react to it that matters.', 'Epictetus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (576, 'The world turns aside to let any man pass who knows where he is going.', 'Epictetus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (577, 'First say to yourself what you would be; and then do what you have to do.', 'Epictetus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (578, 'Keep silence for the most part, and speak only when you must, and then briefly.', 'Epictetus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (579, 'It is impossible for a man to learn what he thinks he already knows.', 'Epictetus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (580, 'One that desires to excel should endeavour in those things that are in themselves most excellent.', 'Epictetus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (581, 'There is only one way to happiness and that is to cease worrying about things which are beyond the power or our will. ', 'Epictetus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (582, 'In times of change learners inherit the earth, while the learned find themselves beautifully equipped to deal with a world that no longer exists.', 'Eric Hoffer', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (583, 'The greatest barrier to success is the fear of failure.', 'Eriksson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (584, 'I like to listen. I have learned a great deal from listening carefully. Most people never listen.', 'Ernest Hemingway', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (585, 'Never mistake motion for action.', 'Ernest Hemingway', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (586, 'Sometimes the most important thing in a whole day is the rest we take between two deep breaths.', 'Etty Hillesum', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (587, 'The wisest men follow their own direction.', 'Euripides', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (588, 'I am a man of fixed and unbending principles, the first of which is to be flexible at all times.', 'Everett Dirksen', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (589, 'There is one thing you have got to learn about our movement. Three people are better than no people.', 'Fannie Hamer', 0);
