INSERT INTO quotes (id, quote, author, used) VALUES (766, 'The future is an opaque mirror. Anyone who tries to look into it sees nothing but the dim outlines of an old and worried face.', 'Jim Bishop', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (767, 'Either you run the day or the day runs you.', 'Jim Rohn', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (768, 'Give whatever you are doing and whoever you are with the gift of your attention.', 'Jim Rohn', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (769, 'The more you care, the stronger you can be.', 'Jim Rohn', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (770, 'If you don''t design your own life plan, chances are you''ll fall into someone else''s plan. And guess what they have planned for you? Not much.', 'Jim Rohn', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (771, 'I can''t change the direction of the wind, but I can adjust my sails to always reach my destination.', 'Jimmy Dean', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (772, 'To free us from the expectations of others, to give us back to ourselves there lies the great, singular power of self-respect.', 'Joan Didion', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (773, 'To free us from the expectations of others, to give us back to ourselves - there lies the great, singular power of self-respect.', 'Joan Didion', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (774, 'If you aren''t going all the way, why go at all?', 'Joe Namath', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (775, 'Believe deep down in your heart that you''re destined to do great things.', 'Joe Paterno', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (776, 'Difficulties increase the nearer we get to the goal.', 'Johann Wolfgang von Goethe', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (777, 'Great talent finds happiness in execution.', 'Johann Wolfgang von Goethe', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (778, 'Character develops itself in the stream of life.', 'Johann Wolfgang von Goethe', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (779, 'A really great talent finds its happiness in execution.', 'Johann Wolfgang von Goethe', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (780, 'Mountains cannot be surmounted except by winding paths.', 'Johann Wolfgang von Goethe', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (781, 'Knowing is not enough; we must apply!', 'Johann Wolfgang von Goethe', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (782, 'In the end we retain from our studies only that which we practically apply.', 'Johann Wolfgang von Goethe', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (783, 'The person born with a talent they are meant to use will find their greatest happiness in using it.', 'Johann Wolfgang von Goethe', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (784, 'People are so constituted that everybody would rather undertake what they see others do, whether they have an aptitude for it or not.', 'Johann Wolfgang von Goethe', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (785, 'If you must tell me your opinions, tell me what you believe in. I have plenty of doubts of my own.', 'Johann Wolfgang von Goethe', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (786, 'Treat people as if they were what they ought to be and you help them to become what they are capable of being.', 'Johann Wolfgang von Goethe', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (787, 'Correction does much, but encouragement does more.', 'Johann Wolfgang von Goethe', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (788, 'Kindness is the golden chain by which society is bound together.', 'Johann Wolfgang von Goethe', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (789, 'Wherever a man may happen to turn, whatever a man may undertake, he will always end up by returning to the path which nature has marked out for him.', 'Johann Wolfgang von Goethe', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (790, 'The really unhappy person is the one who leaves undone what they can do, and starts doing what they don''t understand; no wonder they come to grief.', 'Johann Wolfgang von Goethe', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (791, 'Sometimes our fate resembles a fruit tree in winter. Who would think that those branches would turn green again and blossom, but we hope it, we know it.', 'Johann Wolfgang von Goethe', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (792, 'To speak gratitude is courteous and pleasant, to enact gratitude is generous and noble, but to live gratitude is to touch Heaven.', 'Johannes Gaertner', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (793, 'You cannot have what you do not want.', 'John Acosta', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (794, 'Patience and perseverance have a magical effect before which difficulties disappear and obstacles vanish.', 'John Adams', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (795, 'There are things so deep and complex that only intuition can reach it in our stage of development as human beings.', 'John Astin', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (796, 'Happiness often sneaks in through a door you didn''t know you left open.', 'John Barrymore', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (797, 'The bird of paradise alights only upon the hand that does not grasp.', 'John Berry', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (798, 'It''s easier to do trivial things that are urgent than it is to do important things that are not, like thinking. And it''s also easier to do little things we know we can do than to start on big things that we''re not so sure about.', 'John Cleese', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (799, 'Slow down and everything you are chasing will come around and catch you.', 'John De Paola', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (800, 'Without some goals and some efforts to reach it, no man can live.', 'John Dewey', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (801, 'Conflict is the gadfly of thought. It stirs us to observation and memory. It instigates to invention. It shocks us out of sheep-like passivity, and sets us at noting and contriving.', 'John Dewey', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (802, 'Arriving at one point is the starting point to another.', 'John Dewey', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (803, 'Every great advance in science has issued from a new audacity of the imagination.', 'John Dewey', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (804, 'The self is not something ready-made, but something in continuous formation through choice of action.', 'John Dewey', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (805, 'Fortune befriends the bold.', 'John Dryden', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (806, 'A thing well said will be wit in all languages.', 'John Dryden', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (807, 'All the great performers I have worked with are fuelled by a personal dream.', 'John Eliot', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (808, 'As we express our gratitude, we must never forget that the highest appreciation is not to utter words, but to live by them.', 'John F. Kennedy', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (809, 'Never tell a young person that anything cannot be done. God may have been waiting centuries for someone ignorant enough of the impossible to do that very thing.', 'John Holmes', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (810, 'An ounce of emotion is equal to a ton of facts.', 'John Junor', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (811, 'Change is the law of life. And those who look only to the past or present are certain to miss the future.', 'John Kennedy', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (812, 'Let us resolve to be masters, not the victims, of our history, controlling our own destiny without giving way to blind suspicions and emotions.', 'John Kennedy', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (813, 'Love is the flower you''ve got to let grow.', 'John Lennon', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (814, 'Reality leaves a lot to the imagination.', 'John Lennon', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (815, 'Time you enjoy wasting, was not wasted.', 'John Lennon', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (816, 'Yeah we all shine on, like the moon, and the stars, and the sun.', 'John Lennon', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (817, 'You may say I''m a dreamer, but I''m not the only one, I hope someday you will join us, and the world will live as one.', 'John Lennon', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (818, 'Life is what happens while you are making other plans.', 'John Lennon', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (819, 'Time you enjoyed wasting was not wasted.', 'John Lennon', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (820, 'Life is what happens to you while you''re busy making other plans.', 'John Lennon', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (821, 'You may say I''m a dreamer, but I''m not the only one, I hope someday you will join us, and the world will live as one.', 'John Lennon', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (822, 'I have always thought the actions of men the best interpreters of their thoughts.', 'John Locke', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (823, 'A day of worry is more exhausting than a day of work.', 'John Lubbock', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (824, 'What we see depends mainly on what we look for.', 'John Lubbock', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (825, 'To listen well is as powerful a means of communication and influence as to talk well.', 'John Marshall', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (826, 'When one tugs at a single thing in nature, he finds it attached to the rest of the world.', 'John Muir', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (827, 'Not what we have but what we enjoy constitutes our abundance.', 'John Petit-Senn', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (828, 'Life is movement-we breathe, we eat, we walk, we move!', 'John Pierrakos', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (829, 'The only real mistake is the one from which we learn nothing.', 'John Powell', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (830, 'If your actions inspire others to dream more, learn more, do more and become more, you are a leader.', 'John Quincy Adams', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (831, 'Quality is never an accident; it is always the result of intelligent effort.', 'John Ruskin', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (832, 'Sunshine is delicious, rain is refreshing, wind braces us up, snow is exhilarating; there is really no such thing as bad weather, only different kinds of good weather.', 'John Ruskin', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (833, 'If you''re in a bad situation, don''t worry it''ll change. If you''re in a good situation, don''t worry it''ll change.', 'John Simone', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (834, 'It is a common experience that a problem difficult at night is resolved in the morning after the committee of sleep has worked on it.', 'John Steinbeck', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (835, 'If we could learn to like ourselves, even a little, maybe our cruelties and angers might melt away.', 'John Steinbeck', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (836, 'Dreams come true. Without that possibility, nature would not incite us to have them.', 'John Updike', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (837, 'Never mistake activity for achievement.', 'John Wooden', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (838, 'You can''t let praise or criticism get to you. It''s a weakness to get caught up in either one.', 'John Wooden', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (839, 'You can''t stop the waves, but you can learn to surf.', 'Jon Kabat-Zinn', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (840, 'Intuition will tell the thinking mind where to look next.', 'Jonas Salk', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (841, 'Pick battles big enough to matter, small enough to win.', 'Jonathan Kozol', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (842, 'Discovery consists of seeing what everybody has seen and thinking what nobody else has thought.', 'Jonathan Swift', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (843, 'When we quit thinking primarily about ourselves and our own self-preservation, we undergo a truly heroic transformation of consciousness.', 'Joseph Campbell', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (844, 'Your sacred space is where you can find yourself again and again.', 'Joseph Campbell', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (845, 'To live a creative life, we must lose our fear of being wrong.', 'Joseph Chilton Pearce', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (846, 'He who has imagination without learning has wings but no feet.', 'Joseph Joubert', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (847, 'A fine quotation is a diamond on the finger of a man of wit, and a pebble in the hand of a fool.', 'Joseph Roux', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (848, 'I believe in one thing only, the power of human will.', 'Joseph Stalin', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (849, 'Trust your hunches. They''re usually based on facts filed away just below the conscious level.', 'Joyce Brothers', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (850, 'It is through science that we prove, but through intuition that we discover.', 'Jules Poincare', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (851, 'Some people thrive on huge, dramatic change. Some people prefer the slow and steady route. Do what''s right for you.', 'Julie Morgenstern', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (852, 'Be what you are. This is the first step toward becoming better than you are.', 'Julius Charles Hare', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (853, 'A little knowledge that acts is worth infinitely more than much knowledge that is idle.', 'Kahlil Gibran', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (854, 'To understand the heart and mind of a person, look not at what he has already achieved, but at what he aspires to do.', 'Kahlil Gibran', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (855, 'Beauty is not in the face; beauty is a light in the heart.', 'Kahlil Gibran', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (856, 'We choose our joys and sorrows long before we experience them.', 'Kahlil Gibran', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (857, 'Be like the flower, turn your face to the sun.', 'Kahlil Gibran', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (858, 'Life is change. Growth is optional. Choose wisely.', 'Karen Clark', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (859, 'Make it a rule of life never to regret and never to look back. Regret is an appalling waste of energy; you can''t build on it; it''s only for wallowing in.', 'Katherine Mansfield', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (860, 'All that is necessary is to accept the impossible, do without the indispensable, and bear the intolerable.', 'Kathleen Norris', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (861, 'If you''re not prepared to be wrong, you''ll never come up with anything original.', 'Ken Robinson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (862, 'To be upset over what you don''t have is to waste what you do have.', 'Ken S. Keyes', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (863, 'We must embrace pain and burn it as fuel for our journey.', 'Kenji Miyazawa', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (864, 'We learn what we have said from those who listen to our speaking.', 'Kenneth Patton', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (865, 'With courage you will dare to take risks, have the strength to be compassionate, and the wisdom to be humble. Courage is the foundation of integrity.', 'Keshavan Nair', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (866, 'You won''t skid if you stay in a rut.', 'Kin Hubbard', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (867, 'If you kick a stone in anger, you''ll hurt your own foot.', 'Korean proverb', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (868, 'Be gentle first with yourself if you wish to be gentle with others.', 'Lama Yeshe', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (869, 'It is never too late. Even if you are going to die tomorrow, keep yourself straight and clear and be a happy human being today.', 'Lama Yeshe', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (870, 'Be the chief but never the lord.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (871, 'To lead people walk behind them.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (872, 'Doing nothing is better than being busy doing nothing.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (873, 'Anticipate the difficult by managing the easy.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (874, 'He who talks more is sooner exhausted.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (875, 'He who is contented is rich.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (876, 'The journey of a thousand miles begins with one step.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (877, 'An ant on the move does more than a dozing ox', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (878, 'If you correct your mind, the rest of your life will fall into place.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (879, 'If you would take, you must first give, this is the beginning of intelligence.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (880, 'The wise man does not lay up his own treasures. The more he gives to others, the more he has for his own.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (881, 'Great indeed is the sublimity of the Creative, to which all beings owe their beginning and which permeates all heaven.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (882, 'At the center of your being you have the answer; you know who you are and you know what you want.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (883, 'When you are content to be simply yourself and don''t compare or compete, everybody will respect you.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (884, 'All difficult things have their origin in that which is easy, and great things in that which is small.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (885, 'I have just three things to teach: simplicity, patience, compassion. These three are your greatest treasures.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (886, 'When you realize there is nothing lacking, the whole world belongs to you.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (887, 'By letting it go it all gets done. The world is won by those who let it go. But when you try and try. The world is beyond the winning.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (888, 'He who conquers others is strong; He who conquers himself is mighty.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (889, 'He who obtains has little. He who scatters has much.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (890, 'Silence is a source of great strength.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (891, 'If you do not change direction, you may end up where you are heading.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (892, 'From wonder into wonder existence opens.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (893, 'He who knows himself is enlightened.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (894, 'Great acts are made up of small deeds.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (895, 'Nothing is softer or more flexible than water, yet nothing can resist it.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (896, 'When I let go of what I am, I become what I might be.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (897, 'He who controls others may be powerful, but he who has mastered himself is mightier still.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (898, 'To see things in the seed, that is genius.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (899, 'The key to growth is the introduction of higher dimensions of consciousness into our awareness.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (900, 'He who knows, does not speak. He who speaks, does not know.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (901, 'Kindness in words creates confidence. Kindness in thinking creates profoundness. Kindness in giving creates love.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (902, 'A leader is best when people barely know he exists, when his work is done, his aim fulfilled, they will say: we did it ourselves.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (903, 'He who knows others is wise. He who knows himself is enlightened.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (904, 'One who is too insistent on his own views, finds few to agree with him.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (905, 'Give a man a fish and you feed him for a day. Teach him how to fish and you feed him for a lifetime.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (906, 'He who knows that enough is enough will always have enough.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (907, 'Music in the soul can be heard by the universe.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (908, 'The power of intuitive understanding will protect you from harm until the end of your days.', 'Lao Tzu', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (909, 'A goal without a plan is just a wish.', 'Larry Elder', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (910, 'Arrogance and rudeness are training wheels on the bicycle of life for weak people who cannot keep their balance without them.', 'Laura Teresa Marquez', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (911, 'Imagination is the highest kite one can fly.', 'Lauren Bacall', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (912, 'Sometimes the biggest act of courage is a small one.', 'Lauren Raffo', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (913, 'There are two kinds of failures: those who thought and never did, and those who did and never thought.', 'Laurence J. Peter', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (914, 'If you don''t know where you are going, you will probably end up somewhere else.', 'Lawrence Peter', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (915, 'Great is the art of beginning, but greater is the art of ending.', 'Lazurus Long', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (916, 'People seldom notice old clothes if you wear a big smile.', 'Lee Mildon', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (917, 'I think you can have moderate success by copying something else, but if you really want to knock it out of the park, you have to do something different and take chances.', 'Lee Womack', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (918, 'Always be smarter than the people who hire you.', 'Lena Horne', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (919, 'Blessed is the person who is too busy to worry in the daytime, and too sleepy to worry at night.', 'Leo Aikman', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (920, 'Never idealize others. They will never live up to your expectations.', 'Leo Buscaglia', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (921, 'Don''t smother each other. No one can grow in the shade.', 'Leo F. Buscaglia', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (922, 'The two most powerful warriors are patience and time.', 'Leo Tolstoy', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (923, 'Everyone thinks of changing the world, but no one thinks of changing himself.', 'Leo Tolstoy', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (924, 'We lost because we told ourselves we lost.', 'Leo Tolstoy', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (925, 'The free man is he who does not fear to go to the end of his thought.', 'Leon Blum', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (926, 'The only difference between your abilities and others is the ability to put yourself in their shoes and actually try.', 'Leonardo Ruiz', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (927, 'Who sows virtue reaps honour.', 'Leonardo da Vinci', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (928, 'All our knowledge has its origins in our perceptions.', 'Leonardo da Vinci', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (929, 'Nothing strengthens authority so much as silence.', 'Leonardo da Vinci', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (930, 'Iron rusts from disuse; water loses its purity from stagnation... even so does inaction sap the vigour of the mind.', 'Leonardo da Vinci', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (931, 'He who is fixed to a star does not change his mind.', 'Leonardo da Vinci', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (932, 'Time stays long enough for anyone who will use it.', 'Leonardo da Vinci', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (933, 'In rivers, the water that you touch is the last of what has passed and the first of that which comes; so with present time.', 'Leonardo da Vinci', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (934, 'I have been impressed with the urgency of doing. Knowing is not enough; we must apply. Being willing is not enough; we must do.', 'Leonardo da Vinci', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (935, 'Shoot for the moon. Even if you miss, you''ll land among the stars.', 'Les Brown', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (936, 'To forgive is to set a prisoner free and realize that prisoner was you.', 'Lewis B. Smedes', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (937, 'People may doubt what you say, but they will believe what you do.', 'Lewis Cass', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (938, 'Nobody will believe in you unless you believe in yourself.', 'Liberace', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (939, 'I always wanted to be somebody, but I should have been more specific.', 'Lily Tomlin', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (940, 'I have done my best: that is about all the philosophy of living one needs.', 'Lin Yutang', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (941, 'There is a way that nature speaks, that land speaks. Most of the time we are simply not patient enough, quiet enough, to pay attention to the story.', 'Linda Hogan', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (942, 'That''s the risk you take if you change: that people you''ve been involved with won''t like the new you. But other people who do will come along.', 'Lisa Alther', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (943, 'Those who try to do something and fail are infinitely better than those who try nothing and succeed.', 'Lloyd Jones', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (944, 'The shortest answer is doing.', 'Lord Herbert', 0);
