INSERT INTO quotes (id, quote, author, used) VALUES (1120, 'Men in general judge more from appearances than from reality. All men have eyes, but few have the gift of penetration.', 'Niccolo Machiavelli', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1121, 'How wonderful that we have met with a paradox. Now we have some hope of making progress.', 'Niels Bohr', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1122, 'You need chaos in your soul to give birth to a dancing star.', 'Nietzsche', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1123, 'Our virtues and our failings are inseparable, like force and matter. When they separate, man is no more.', 'Nikola Tesla', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1124, 'Let the future tell the truth, and evaluate each one according to his work and accomplishments. The present is theirs; the future, for which I have really worked, is mine.', 'Nikola Tesla', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1125, 'By believing passionately in something that does not yet exist, we create it.', 'Nikos Kazantzakis', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1126, 'If you don''t go after what you want, you''ll never have it. If you don''t ask, the answer is always no. If you don''t step forward, you''re always in the same place.', 'Nora Roberts', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1127, 'Never deny a diagnosis, but do deny the negative verdict that may go with it.', 'Norman Cousins', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1128, 'If you want things to be different, perhaps the answer is to become different yourself.', 'Norman Peale', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1129, 'The truth of the matter is that you always know the right thing to do. The hard part is doing it.', 'Norman Schwarzkopf', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1130, 'Each misfortune you encounter will carry in it the seed of tomorrows good luck.', 'Og Mandino', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1131, 'I will love the light for it shows me the way, yet I will endure the darkness because it shows me the stars.', 'Og Mandino', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1132, 'I seek constantly to improve my manners and graces, for they are the sugar to which all are attracted.', 'Og Mandino', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1133, 'Always do your best. What you plant now, you will harvest later.', 'Og Mandino', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1134, 'Always seek out the seed of triumph in every adversity.', 'Og Mandino', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1135, 'Failure will never overtake me if my determination to succeed is strong enough.', 'Og Mandino', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1136, 'You have to take it as it happens, but you should try to make it happen the way you want to take it.', 'Old German proverb', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1137, 'What lies behind us and what lies before us are small matters compared to what lies within us.', 'Oliver Wendell Holmes, Sr.', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1138, 'A man may fulfil the object of his existence by asking a question he cannot answer, and attempting a task he cannot achieve.', 'Oliver Wendell Holmes, Sr.', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1139, 'Love is the master key that opens the gates of happiness.', 'Oliver Wendell Holmes, Sr.', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1140, 'Fame usually comes to those who are thinking about something else.', 'Oliver Wendell Holmes, Sr.', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1141, 'Follow your instincts. That is where true wisdom manifests itself.', 'Oprah Winfrey', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1142, 'I don''t believe in failure. It is not failure if you enjoyed the process.', 'Oprah Winfrey', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1143, 'If you want your life to be more rewarding, you have to change the way you think.', 'Oprah Winfrey', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1144, 'The biggest adventure you can ever take is to live the life of your dreams.', 'Oprah Winfrey', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1145, 'Although there may be tragedy in your life, there''s always a possibility to triumph. It doesn''t matter who you are, where you come from. The ability to triumph begins with you. Always.', 'Oprah Winfrey', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1146, 'With every experience, you alone are painting your own canvas, thought by thought, choice by choice.', 'Oprah Winfrey', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1147, 'I don''t believe in failure. It''s not failure if you enjoyed the process.', 'Oprah Winfrey', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1148, 'Lots of people want to ride with you in the limo, but what you want is someone who will take the bus with you when the limo breaks down.', 'Oprah Winfrey', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1149, 'Don''t settle for a relationship that won''t let you be yourself.', 'Oprah Winfrey', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1150, 'The Creator has not given you a longing to do that which you have no ability to do.', 'Orison Marden', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1151, 'Most of our obstacles would melt away if, instead of cowering before them, we should make up our minds to walk boldly through them.', 'Orison Marden', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1152, 'All men who have achieved great things have been great dreamers.', 'Orison Marden', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1153, 'Experience is simply the name we give our mistakes.', 'Oscar Wilde', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1154, 'The only thing to do with good advice is to pass it on. It is never of any use to oneself.', 'Oscar Wilde', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1155, 'The aim of life is self-development. To realize ones nature perfectly that is what each of us is here for.', 'Oscar Wilde', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1156, 'The smallest act of kindness is worth more than the grandest intention.', 'Oscar Wilde', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1157, 'Anybody can make history. Only a great man can write it.', 'Oscar Wilde', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1158, 'Be yourself; everyone else is already taken.', 'Oscar Wilde', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1159, 'Be yourself; everyone else is already taken.', 'Oscar Wilde', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1160, 'The cause is hidden. The effect is visible to all.', 'Ovid', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1161, 'All things change; nothing perishes.', 'Ovid', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1162, 'Chance is always powerful. Let your hook be always cast; in the pool where you least expect it, there will be a fish.', 'Ovid', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1163, 'Let your hook always be cast; in the pool where you least expect it, there will be a fish.', 'Ovid', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1164, 'Take rest; a field that has rested gives a bountiful crop.', 'Ovid', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1165, 'Mind is everything: muscle, pieces of rubber. All that I am, I am because of my mind.', 'Paavo Nurmi', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1166, 'Everything you can imagine is real.', 'Pablo Picasso', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1167, 'Inspiration exists, but it has to find us working.', 'Pablo Picasso', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1168, 'He can who thinks he can, and he can''t who thinks he can''t. This is an inexorable, indisputable law.', 'Pablo Picasso', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1169, 'I am always doing that which I cannot do, in order that I may learn how to do it.', 'Pablo Picasso', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1170, 'I am always doing that which I can not do, in order that I may learn how to do it.', 'Pablo Picasso', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1171, 'Action is the foundational key to all success.', 'Pablo Picasso', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1172, 'I begin with an idea and then it becomes something else.', 'Pablo Picasso', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1173, 'All children are artists. The problem is how to remain an artist once he grows up.', 'Pablo Picasso', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1174, 'Courage is not the absence of fear, but simply moving on with dignity despite that fear.', 'Pat Riley', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1175, 'Forgiveness does not change the past, but it does enlarge the future.', 'Paul Boese', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1176, 'The awareness of our own strength makes us modest.', 'Paul Cezanne', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1177, 'The most dangerous way to lose time is not to spend it having fun, but to spend it doing fake work. When you spend time having fun, you know you''re being self-indulgent.', 'Paul Graham', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1178, 'That''s the thing about counter-intuitive ideas, they contradict your intuitions. So, they seem wrong.', 'Paul Graham', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1179, 'Decision is a risk rooted in the courage of being free.', 'Paul Tillich', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1180, 'Write your plans in pencil and give God the eraser.', 'Paulo Coelho', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1181, 'One faces the future with ones past.', 'Pearl Buck', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1182, 'Growth itself contains the germ of happiness.', 'Pearl Buck', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1183, 'Every great mistake has a halfway moment, a split second when it can be recalled and perhaps remedied.', 'Pearl Buck', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1184, 'You cannot make yourself feel something you do not feel, but you can make yourself do right in spite of your feelings.', 'Pearl Buck', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1185, 'The truth is always exciting. Speak it, then. Life is dull without it.', 'Pearl Buck', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1186, 'The secret of joy in work is contained in one word excellence. To know how to do something well is to enjoy it.', 'Pearl Buck', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1187, 'The secret of joy in work is contained in one word: excellence. To know how to do something well is to enjoy it.', 'Pearl Buck', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1188, 'The truth you believe and cling to makes you unavailable to hear anything new.', 'Pema Chodron', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1189, 'When you begin to touch your heart or let your heart be touched, you begin to discover that it''s bottomless.', 'Pema Chodron', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1190, 'If we learn to open our hearts, anyone, including the people who drive us crazy, can be our teacher.', 'Pema Chodron', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1191, 'Nothing ever goes away until it has taught us what we need to know.', 'Pema Chodron', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1192, 'The greatest obstacle to connecting with our joy is resentment.', 'Pema Chodron', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1193, 'The future is completely open, and we are writing it moment to moment.', 'Pema Chodron', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1194, 'To be fully alive, fully human, and completely awake is to be continually thrown out of the nest.', 'Pema Chodron', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1195, 'It isn''t what happens to us that causes us to suffer; it''s what we say to ourselves about what happens.', 'Pema Chodron', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1196, 'Fear not for the future, weep not for the past.', 'Percy Shelley', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1197, 'Time is the wisest counsellor of all.', 'Pericles', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1198, 'Efficiency is doing things right; effectiveness is doing the right things.', 'Peter Drucker', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1199, 'Follow effective action with quiet reflection. From the quiet reflection will come even more effective action.', 'Peter Drucker', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1200, 'There is nothing so useless as doing efficiently that which should not be done at all.', 'Peter Drucker', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1201, 'You cannot predict the future, but you can create it.', 'Peter Drucker', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1202, 'Until we can manage time, we can manage nothing else.', 'Peter Drucker', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1203, 'Meaning is not what you start with but what you end up with.', 'Peter Elbow', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1204, 'Moments of complete apathy are the best for new creations.', 'Philip Breedveld', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1205, 'Either I will find a way, or I will make one.', 'Philip Sidney', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1206, 'The beginning of wisdom is found in doubting; by doubting we come to the question, and by seeking we may come upon the truth.', 'Pierre Abelard', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1207, 'The pain passes, but the beauty remains.', 'Pierre Auguste Renoir', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1208, 'A good decision is based on knowledge and not on numbers.', 'Plato', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1209, 'Bodily exercise, when compulsory, does no harm to the body; but knowledge which is acquired under compulsion obtains no hold on the mind.', 'Plato', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1210, 'Good actions give strength to ourselves and inspire good actions in others.', 'Plato', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1211, 'Wise men talk because they have something to say; fools, because they have to say something.', 'Plato', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1212, 'Knowledge has three degrees opinion, science, illumination. The means or instrument of the first is sense; of the second, dialectic; of the third, intuition.', 'Plotinus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1213, 'What we achieve inwardly will change outer reality.', 'Plutarch', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1214, 'Know how to listen, and you will profit even from those who talk badly.', 'Plutarch', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1215, 'To make no mistakes is not in the power of man; but from their errors and mistakes the wise and good learn wisdom for the future.', 'Plutarch', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1216, 'Only do what your heart tells you.', 'Princess Diana', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1217, 'A rolling stone gathers no moss.', 'Publilius Syrus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1218, 'While we stop to think, we often miss our opportunity.', 'Publilius Syrus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1219, 'Better be ignorant of a matter than half know it.', 'Publilius Syrus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1220, 'I have often regretted my speech, never my silence.', 'Publilius Syrus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1221, 'Do not turn back when you are just at the goal.', 'Publilius Syrus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1222, 'Never promise more than you can perform.', 'Publilius Syrus', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1223, 'If I am not for myself, who will be for me? If I am not for others, what am I? And if not now, when?', 'Rabbi Hillel', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1224, 'We read the world wrong and say that it deceives us.', 'Rabindranath Tagore', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1225, 'If facts are the seeds that later produce knowledge and wisdom, then the emotions and the impressions of the senses are the fertile soil in which the seeds must grow.', 'Rachel Carson', 0);
