INSERT INTO quotes (id, quote, author, used) VALUES (1229, 'Skill to do comes of doing.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1230, 'The years teach much which the days never know.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1231, 'Our distrust is very expensive.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1232, 'Good luck is another name for tenacity of purpose.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1233, 'Life is a progress, and not a station.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1234, 'The world makes way for the man who knows where he is going.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1235, 'Life is a succession of lessons, which must be lived to be understood.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1236, 'Great are they who see that spiritual is stronger than any material force, that thoughts rule the world.', 'Ralph Emerson', 0);
