INSERT INTO quotes (id, quote, author, used) VALUES (1239, 'It is one of the blessings of old friends that you can afford to be stupid with them.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1240, 'If the stars should appear but one night every thousand years how man would marvel and adore.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1241, 'Do not be too timid and squeamish about your reactions. All life is an experiment. The more experiments you make the better.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1242, 'Do not go where the path may lead, go instead where there is no path and leave a trail.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1243, 'Self-trust is the first secret of success.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1244, 'Go put your creed into the deed. Nor speak with double tongue.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1245, 'We aim above the mark to hit the mark.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1246, 'Nature is a mutable cloud which is always and never the same.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1247, 'Build a better mousetrap and the world will beat a path to your door.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1248, 'Nothing is at last sacred but the integrity of your own mind.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1249, 'Nothing great was ever achieved without enthusiasm.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1250, 'Each man has his own vocation; his talent is his call. There is one direction in which all space is open to him.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1251, 'Truth, and goodness, and beauty are but different faces of the same all.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1252, 'To be great is to be misunderstood.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1253, 'Make the most of yourself, for that is all there is of you.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1254, 'Everything in the universe goes by indirection. There are no straight lines.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1255, 'Make the most of yourself for that is all there is of you.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1256, 'Thought is the blossom; language the bud; action the fruit behind it.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1257, 'We must be as courteous to a man as we are to a picture, which we are willing to give the advantage of a good light.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1258, 'What is a weed? A plant whose virtues have not yet been discovered.', 'Ralph Emerson', 0);
