INSERT INTO quotes (id, quote, author, used) VALUES (1261, 'In skating over thin ice our safety is in our speed.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1262, 'So is cheerfulness, or a good temper, the more it is spent, the more remains.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1263, 'Bad times have a scientific value. These are occasions a good learner would not miss.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1264, 'The only way to have a friend is to be one.', 'Ralph Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1265, 'Excellence is not a skill. It is an attitude.', 'Ralph Marston', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1266, 'Let go of your attachment to being right, and suddenly your mind is more open. You''re able to benefit from the unique viewpoints of others, without being crippled by your own judgement.', 'Ralph Marston', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1267, 'Our strength grows out of our weaknesses.', 'Ralph Waldo Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1268, 'It is only when the mind and character slumber that the dress can be seen.', 'Ralph Waldo Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1269, 'Happiness is a perfume you cannot pour on others without getting a few drops on yourself.', 'Ralph Waldo Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1270, 'A hero is no braver than an ordinary man, but he is braver five minutes longer.', 'Ralph Waldo Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1271, 'Imagination is not a talent of some men but is the health of every man.', 'Ralph Waldo Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1272, 'Most of the shadows of life are caused by standing in our own sunshine.', 'Ralph Waldo Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1273, 'Do not follow where the path may lead. Go, instead, where there is no path and leave a trail.', 'Ralph Waldo Emerson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1274, 'Living at risk is jumping off the cliff and building your wings on the way down.', 'Ray Bradbury', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1275, 'You get peace of mind not by thinking about it or imagining it, but by quietening and relaxing the restless mind.', 'Remez Sasson', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1276, 'It is not enough to have a good mind; the main thing is to use it well.', 'Rene Descartes', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1277, 'The greatest minds are capable of the greatest vices as well as of the greatest virtues.', 'Rene Descartes', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1278, 'Divide each difficulty into as many parts as is feasible and necessary to resolve it.', 'Rene Descartes', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1279, 'Argue for your limitations, and sure enough they''re yours.', 'Richard Bach', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1280, 'In order to win, you must expect to win.', 'Richard Bach', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1281, 'The simplest things are often the truest.', 'Richard Bach', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1282, 'To bring anything into your life, imagine that it''s already there.', 'Richard Bach', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1283, 'Strong beliefs win strong men, and then make them stronger.', 'Richard Bach', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1284, 'Every problem has a gift for you in its hands.', 'Richard Bach', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1285, 'The best way to pay for a lovely moment is to enjoy it.', 'Richard Bach', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1286, 'In order to live free and happily you must sacrifice boredom. It is not always an easy sacrifice.', 'Richard Bach', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1287, 'You are always free to change your mind and choose a different future, or a different past.', 'Richard Bach', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1288, 'Your friends will know you better in the first minute you meet than your acquaintances will know you in a thousand years.', 'Richard Bach', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1289, 'If you love someone, set them free. If they come back they''re yours; if they don''t they never were.', 'Richard Bach', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1290, 'Bad things are not the worst things that can happen to us. Nothing is the worst thing that can happen to us!', 'Richard Bach', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1291, 'Can miles truly separate you from friends... If you want to be with someone you love, aren''t you already there?', 'Richard Bach', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1292, 'Don''t turn away from possible futures before you''re certain you don''t have anything to learn from them.', 'Richard Bach', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1293, 'Don''t believe what your eyes are telling you. All they show is limitation. Look with your understanding, find out what you already know, and you''ll see the way to fly.', 'Richard Bach', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1294, 'Sooner or later, those who win are those who think they can.', 'Richard Bach', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1295, 'Happiness is the reward we get for living to the highest right we know.', 'Richard Bach', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1296, 'Every gift from a friend is a wish for your happiness.', 'Richard Bach', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1297, 'Learning is finding out what you already know.', 'Richard Bach', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1298, 'Ask yourself the secret of your success. Listen to your answer, and practice it.', 'Richard Bach', 0);
INSERT INTO quotes (id, quote, author, used) VALUES (1299, 'The meaning I picked, the one that changed my life: Overcome fear, behold wonder.', 'Richard Bach', 0);
